49		// StateNominal is the bench as seeded: the upstream is up, the proxy is in service.
50		StateNominal BenchState = ""
51		// StateUpstreamCut is the bench after cut-upstream: the upstream has no replica.
52		StateUpstreamCut BenchState = "upstream-cut"
53	)
