55	// defaultRecordTimeout bounds one request of the recorder when RecordOptions.RequestTimeout is 0.
56	const defaultRecordTimeout = 15 * time.Second
57	
58	// recordRequestTimeout is the timeout of one request of a run: the option, or the default.
59	// TODO(DEVDESK-580, PR2): skeleton, the green phase gives it its behavior.
60	func recordRequestTimeout(RecordOptions) time.Duration { return 0 }
61	
62	// RecordOptions says what to record and against which bench.
63	type RecordOptions struct {
64		// Origins maps the Host of a fixture ("127.0.0.1:30481") to the base URL that
65		// reaches it. Each key must be a loopback host:port of the descriptor and each
66		// URL a loopback origin (IsLoopbackRESTHost), no user information. The REST
67		// origin (first host of the descriptor, REST node port) is required: the data
68		// set is compared through it.
69		Origins    map[string]string
70		Descriptor Descriptor
71		Secrets    Secrets
72		// Dir is the folder of the campaigns; empty means nexusfixture.SourceDir().
73		Dir string
74		// Campaigns limits the run to these campaigns; empty means every folder of Dir.
75		Campaigns []string
76		// Only is an optional glob (path.Match) on fixture names, without ".http".
77		Only string
78		// Now gives the date of the "measured" header; nil means time.Now.
79		Now func() time.Time
80		// DenyTerms are extra terms no written fixture may hold (the external deny list).
81		DenyTerms []string
82		// State is the state the bench is in: only the fixtures whose "state" header
83		// starts with it are recorded, the others are reported skipped. The zero value is
84		// StateNominal, which takes the fixtures with no "state" header.
85		State BenchState
86		// AllowCacheEffects lets a fixture that says "effect: caches" be sent: such a
87		// request can leave an image in the proxy, and the bench has then to be reset.
88		AllowCacheEffects bool
89		// RequestTimeout bounds one request of the run, connection included; 0 means
90		// defaultRecordTimeout (15 s).
91		RequestTimeout time.Duration
92	}
