94	// RecordReport lists the fixtures of a run as "<campaign>/<name>". A Skipped
95	// entry is followed by ": <reason>".
96	type RecordReport struct {
97		Written, Unchanged, Skipped []string
98		// CacheEffects are the fixtures of the run that were sent with "effect: caches":
99		// the bench can hold a cached image because of them, and needs a reset.
100		CacheEffects []string
101	}
