103	// recordJob is one fixture to replay.
104	type recordJob struct {
105		campaign string
106		name     string // "<campaign>/<file name without .http>"
107		path     string
108		current  nexusfixture.Fixture
109		user     string // "" for an anonymous fixture
110		password string
111		origin   string
112	}
113	
114	// recordWrite is a fixture file to replace, held back until every answer passed.
115	type recordWrite struct {
116		name string
117		path string
118		data []byte
119	}
120	
121	// RecordFixtures regenerates the recorded fixtures from the bench. A fixture is
122	// skipped (reported, never requested) when it says "record: skip" or holds more
123	// than one exchange. A fixture whose answer is the one it already holds, apart
124	// from its date, is left alone, bytes and modification time. Every error is a
125	// *BenchError, free of secrets; on an error nothing is written and the report is
126	// empty.
127	func RecordFixtures(ctx context.Context, o RecordOptions) (RecordReport, error) {
128		if err := ctx.Err(); err != nil {
129			return RecordReport{}, recordError("the recording was cancelled before it started", "run it again", err)
130		}
131		jobs, report, err := planRecording(o)
132		if err != nil {
133			return RecordReport{}, err
134		}
135		if len(jobs) > 0 {
136			if err := checkBenchDataset(ctx, o); err != nil {
137				return RecordReport{}, err
138			}
139		}
140		writes, unchanged, err := gatherAnswers(ctx, o, jobs)
141		if err != nil {
142			return RecordReport{}, err
143		}
144		report.Unchanged = unchanged
145		for i, w := range writes {
146			if err := writeFileAtomic(w.path, w.data, recordedFileMode, recordedDirMode); err != nil {
147				return RecordReport{}, recordError(
148					fmt.Sprintf("%s could not be written (%d fixture(s) of this run were already written)", w.name, i),
149					"check the permissions of the fixtures folder, then record again", err)
150			}
151			report.Written = append(report.Written, w.name)
152		}
153		return report, nil
154	}
155	
156	// recordError returns a BenchError; err is kept for errors.Is and errors.As and
157	// is never printed. A refusal with no underlying error keeps its own cause.
158	func recordError(cause, check string, err error) *BenchError {
159		if err == nil {
160			err = errors.New(cause)
161		}
162		return &BenchError{Kind: Unclassified, Cause: cause, Check: check, Err: err}
163	}
164	
165	// ---- planning: everything is checked before the first request ------------------
166	
167	// planRecording reads the fixtures and refuses anything that must not be sent.
168	func planRecording(o RecordOptions) ([]recordJob, RecordReport, error) {
169		var report RecordReport
170		if err := checkOrigins(o); err != nil {
171			return nil, report, err
172		}
173		if o.Only != "" {
174			if _, err := path.Match(o.Only, ""); err != nil {
175				return nil, report, recordError("the fixture filter is not a valid glob", "write it as a path.Match pattern, e.g. catalog-*", err)
176			}
177		}
178		dir := o.Dir
179		if dir == "" {
180			var err error
181			if dir, err = nexusfixture.SourceDir(); err != nil {
182				return nil, report, recordError("the fixtures folder of the source tree cannot be located", "run the recorder from a build that knows its source tree (not -trimpath)", err)
183			}
184		}
185		if info, err := os.Stat(dir); err != nil || !info.IsDir() {
186			return nil, report, recordError("the fixtures folder "+dir+" is not there", "check the folder", err)
187		}
188		fsys := os.DirFS(dir)
189		campaigns, err := recordCampaigns(dir, fsys, o.Campaigns)
190		if err != nil {
191			return nil, report, err
192		}
193		var jobs []recordJob
194		for _, campaign := range campaigns {
195			entries, err := fs.ReadDir(fsys, campaign)
196			if err != nil {
197				return nil, report, recordError("the campaign "+campaign+" cannot be read", "check the fixtures folder", err)
198			}
199			for _, e := range entries {
200				name, ok := strings.CutSuffix(e.Name(), ".http")
201				if e.IsDir() || !ok {
202					continue
203				}
204				if err := refuseLink(filepath.Join(dir, campaign, e.Name()), campaign+"/"+name); err != nil {
205					return nil, report, err
206				}
207				if o.Only != "" {
208					if match, _ := path.Match(o.Only, name); !match {
209						continue
210					}
211				}
212				job, skipped, err := planFixture(o, fsys, filepath.Join(dir, campaign, e.Name()), campaign, e.Name())
213				switch {
214				case err != nil:
215					return nil, report, err
216				case skipped != "":
217					report.Skipped = append(report.Skipped, campaign+"/"+name+": "+skipped)
218				default:
219					jobs = append(jobs, job)
220				}
221			}
222		}
223		return jobs, report, nil
224	}
225	
226	// refuseLink refuses a campaign folder or a fixture file that is a symbolic
227	// link: a link could carry a run, which sends the bench credentials and rewrites
228	// files, to something that is not in the fixtures folder. A path that cannot be
229	// inspected is left to the read that follows.
230	func refuseLink(filePath, label string) error {
231		if info, err := os.Lstat(filePath); err == nil && info.Mode()&os.ModeSymlink != 0 {
232			return recordError(label+" is a symbolic link", "replace the link with the real file or folder", nil)
233		}
234		return nil
235	}
236	
237	// recordCampaigns returns the campaigns to read: the ones asked for, each a plain
238	// folder name of fsys (dir on disk), or every folder of fsys. A campaign that is
239	// a symbolic link is refused, asked for or found.
240	func recordCampaigns(dir string, fsys fs.FS, wanted []string) ([]string, error) {
241		if len(wanted) == 0 {
242			entries, err := fs.ReadDir(fsys, ".")
243			if err != nil {
244				return nil, recordError("the fixtures folder cannot be read", "check the folder", err)
245			}
246			var all []string
247			for _, e := range entries {
248				if strings.HasPrefix(e.Name(), ".") {
249					continue
250				}
251				if e.Type()&fs.ModeSymlink != 0 {
252					return nil, recordError("the campaign "+e.Name()+" is a symbolic link", "replace the link with the real folder", nil)
253				}
254				if e.IsDir() {
255					all = append(all, e.Name())
256				}
257			}
258			return all, nil
259		}
260		for _, c := range wanted {
261			if c == "." || !fs.ValidPath(c) || strings.Contains(c, "/") {
262				return nil, recordError("the campaign "+strconv.Quote(c)+" is not a campaign name", "name a folder of the fixtures folder, with no path", nil)
263			}
264			if err := refuseLink(filepath.Join(dir, c), c); err != nil {
265				return nil, err
266			}
267			if info, err := fs.Stat(fsys, c); err != nil || !info.IsDir() {
268				return nil, recordError("the campaign "+c+" does not exist", "check the campaign name", err)
269			}
270		}
271		return wanted, nil
272	}
273	
274	// planFixture reads one fixture file. It returns the reason when the fixture is
275	// skipped, an error when it must not be sent.
276	func planFixture(o RecordOptions, fsys fs.FS, filePath, campaign, fileName string) (recordJob, string, error) {
277		label := campaign + "/" + strings.TrimSuffix(fileName, ".http")
278		data, err := fs.ReadFile(fsys, path.Join(campaign, fileName))
279		if err != nil {
280			return recordJob{}, "", recordError(label+" cannot be read", "check the file", err)
281		}
282		f, err := nexusfixture.Parse(campaign, fileName, data)
283		if err != nil {
284			return recordJob{}, "", recordError(label+" is not a valid fixture", "fix the file", err)
285		}
286		if reason, ok := strings.CutPrefix(f.Meta.Record, "skip"); ok {
287			return recordJob{}, strings.TrimSpace(strings.TrimPrefix(reason, ":")), nil
288		}
289		if len(f.Exchanges) != 1 {
290			return recordJob{}, fmt.Sprintf("holds %d exchanges, only one is recorded yet", len(f.Exchanges)), nil
291		}
292		// The file is scanned as it stands: a request header outside Host, the
293		// credentials and Accept, or a query other than n and last, refuses it.
294		if leaks := nexusfixture.CheckLeaks(label, data, recordTerms(o)); len(leaks) > 0 {
295			return recordJob{}, "", recordError(label+" is refused before it is sent: "+describeLeaks(leaks), "fix the file", nil)
296		}
297		ex := f.Exchanges[0]
298		if reason := refusedRequest(ex.Method, ex.Target); reason != "" {
299			return recordJob{}, "", recordError(label+" asks for something the recorder does not send ("+reason+")", "record only GET requests of the closed list of paths", nil)
300		}
301		origin, ok := o.Origins[ex.Host]
302		if !ok {
303			return recordJob{}, "", recordError(label+" is recorded on "+ex.Host+", which has no origin", "give the origin of this host:port", nil)
304		}
305		job := recordJob{campaign: campaign, name: label, path: filePath, current: f, origin: origin}
306		switch f.Identity {
307		case nexusfixture.Admin:
308			job.user, job.password = REDACTED, o.Secrets.AdminPassword
309		case nexusfixture.Pull:
310			job.user, job.password = REDACTED, o.Secrets.PullPassword
311		}
312		if job.user != "" && job.password == "" {
313			return recordJob{}, "", recordError("the bench has no stored password for "+job.user+", the account of "+label, upCheck, nil)
314		}
315		return job, "", nil
316	}
317	
318	// checkOrigins refuses an origin that is not a loopback URL, a key that is not a
319	// loopback host:port of the descriptor, and a run with no REST origin.
320	func checkOrigins(o RecordOptions) error {
321		known := descriptorOrigins(o.Descriptor)
322		for key, base := range o.Origins {
323			if !known[key] {
324				return recordError("the origin of "+key+" is not a loopback host:port of the bench descriptor", "give origins for the hosts and ports the descriptor lists", nil)
325			}
326			if err := requireLoopbackBase(base); err != nil {
327				return err
328			}
329		}
330		rest, ok := restOriginKey(o.Descriptor)
331		if _, have := o.Origins[rest]; !ok || !have {
332			return recordError("no origin is given for the REST port of the bench, which the data set check needs", "give the REST origin of the descriptor", nil)
333		}
334		return nil
335	}
336	
337	// descriptorOrigins is the set of loopback host:port pairs the descriptor
338	// publishes: every host of the descriptor on the REST and the Docker ports.
339	func descriptorOrigins(d Descriptor) map[string]bool {
340		ports := []int{d.REST.NodePort}
341		for _, c := range d.DockerConnectors {
342			ports = append(ports, c.NodePort)
343		}
344		known := map[string]bool{}
345		for _, h := range d.Hosts {
346			host := strings.Trim(h, "[]")
347			if !IsLoopbackRESTHost(host) {
348				continue
349			}
350			for _, p := range ports {
351				known[net.JoinHostPort(host, strconv.Itoa(p))] = true
352			}
353		}
354		return known
355	}
356	
357	// RecordOrigins builds RecordOptions.Origins from the descriptor: one entry per
358	// loopback host and port it publishes (the REST and the Docker ports), keyed
359	// host:port, valued with the http URL on restHost, which is the host of the key
360	// when empty.
361	func RecordOrigins(d Descriptor, restHost string) map[string]string {
362		origins := map[string]string{}
363		for key := range descriptorOrigins(d) {
364			host, portText, err := net.SplitHostPort(key)
365			port, convErr := strconv.Atoi(portText)
366			if err != nil || convErr != nil {
367				continue
368			}
369			if restHost != "" {
370				host = restHost
371			}
372			origins[key] = hostURL(host, port)
373		}
374		return origins
375	}
376	
377	// restOriginKey is the host:port of the REST API: the first host of the
378	// descriptor on the REST node port.
379	func restOriginKey(d Descriptor) (string, bool) {
380		if len(d.Hosts) == 0 || d.REST.NodePort == 0 {
381			return "", false
382		}
383		return net.JoinHostPort(strings.Trim(d.Hosts[0], "[]"), strconv.Itoa(d.REST.NodePort)), true
384	}
385	
386	// The closed list of what the recorder may ask for. A manifest or a blob read
387	// through a proxy repository would cache an image and change the bench, so none
388	// is allowed, whatever the path says.
389	var (
390		recordPaths = []*regexp.Regexp{
391			regexp.MustCompile(`^/v2/(_catalog|[a-z0-9._/-]+/tags/list)?$`),
392			regexp.MustCompile(`^/v2/[a-z0-9._-]+(/[a-z0-9._-]+)*/_catalog$`),
393			regexp.MustCompile(`^/repository/[A-Za-z0-9._-]+/v2/_catalog$`),
394			regexp.MustCompile(`^/service/rest/v1/repositories(/[A-Za-z0-9._-]+)*$`),
395		}
396		// recordQueryParam admits one percent escape only: %2F in the value of last,
397		// the form a Nexus group page Link gives the last name (DEVDESK-580).
398		recordQueryParam = regexp.MustCompile(`^(n=[0-9]{1,6}|last=([A-Za-z0-9._/-]|%2[Ff])*)$`)
399	)
400	
401	// refusedRequest returns why a request may not be sent, or "".
402	func refusedRequest(method, target string) string {
403		p, query, hasQuery := strings.Cut(target, "?")
404		switch {
405		case method != http.MethodGet:
406			return "the method is not GET"
407		case strings.Contains(target, "..") || strings.Contains(p, "%"):
408			// An escape in the query is left to recordQueryParam, which lets only %2F
409			// through in the value of last.
410			return "the target holds a dot-dot or an escape"
411		case strings.Contains(p+"/", "/manifests/") || strings.Contains(p+"/", "/blobs/"):
412			return "a manifest or a blob read can change the bench"
413		}
414		listed := false
415		for _, re := range recordPaths {
416			listed = listed || re.MatchString(p)
417		}
418		if !listed {
419			return "the path is not in the closed list"
420		}
421		if hasQuery {
422			for _, param := range strings.Split(query, "&") {
423				if !recordQueryParam.MatchString(param) {
424					return "the query holds more than n and last"
425				}
426			}
427		}
428		return ""
429	}
430	
431	// ---- the data set of the bench ---------------------------------------------------
432	
433	// checkBenchDataset compares, anonymously, what docker-hosted and docker-proxy
434	// list with the data set of the descriptor: a bench that does not hold it would
435	// record answers that are not the ones the fixtures describe. What cannot be read
436	// is a refusal too.
437	func checkBenchDataset(ctx context.Context, o RecordOptions) error {
438		if len(o.Descriptor.Dataset) == 0 {
439			return recordError("the descriptor lists no data set to compare the bench with", "run `mise run nexus-bench:seed`", nil)
440		}
441		key, _ := restOriginKey(o.Descriptor)
442		base := o.Origins[key]
443		for _, repo := range DatasetRepositories() {
444			listed, err := ListImagesAnonymously(ctx, base, repo)
445			if err != nil {
446				return recordError("the listing of "+repo+" could not be read, so the data set of the bench is unknown",
447					"check that the bench answers and that anonymous access is on", err)
448			}
449			diffs, ok := CompareDataset(DatasetIn(o.Descriptor.Dataset, repo), listed)
450			if !ok {
451				return recordError("the listing of "+repo+" gives no digest, so the data set of the bench cannot be compared", resetCheck, nil)
452			}
453			if diffs > 0 {
454				return recordError(fmt.Sprintf("%s differs from the data set of the descriptor (%d image(s))", repo, diffs), resetCheck, nil)
455			}
456		}
457		return nil
458	}
459	
460	// DatasetRepositories are the two repositories that hold the data set. The group
461	// is never read: a read through it can cache an image.
462	func DatasetRepositories() []string {
463		return []string{dockerHostedRepository, dockerProxyRepository}
464	}
465	
466	// DatasetIn returns the images of the data set that repo holds: the hosted ones
467	// in docker-hosted, the ones cached in the proxy in docker-proxy.
468	func DatasetIn(images []DescriptorImage, repo string) []DescriptorImage {
469		var out []DescriptorImage
470		for _, img := range images {
471			hosted := repo == dockerHostedRepository && img.Location == string(LocationHosted)
472			cached := repo == dockerProxyRepository && img.CachedInProxy
473			if hosted || cached {
474				out = append(out, img)
475			}
476		}
477		return out
478	}
479	
480	// CompareDataset counts the images of a repository that are missing, have
481	// another digest, or are not in the data set. ok is false when the listing gives
482	// no digest for an image that is there, which makes the comparison impossible.
483	func CompareDataset(want []DescriptorImage, listed []ListedImage) (diffs int, ok bool) {
484		have := make(map[string]string, len(listed))
485		for _, img := range listed {
486			have[img.Name+":"+img.Tag] = img.Digest
487		}
488		for _, img := range want {
489			key := img.Name + ":" + img.Tag
490			digest, found := have[key]
491			delete(have, key)
492			switch {
493			case !found:
494				diffs++
495			case digest == "":
496				return 0, false
497			case digest != img.Digest:
498				diffs++
499			}
500		}
501		return diffs + len(have), true
502	}
503	
504	// ---- gathering the answers ------------------------------------------------------
505	
506	// gatherAnswers asks every job and returns the files to write and the fixtures
507	// that did not change. The first problem ends the run: nothing is written yet.
508	func gatherAnswers(ctx context.Context, o RecordOptions, jobs []recordJob) (writes []recordWrite, unchanged []string, err error) {
509		clients := map[string]*client{}
510		defer func() {
511			for _, c := range clients {
512				c.closeIdle()
513			}
514		}()
515		now := time.Now
516		if o.Now != nil {
517			now = o.Now
518		}
519		date := now().Format(recordedDateLayout)
520		for _, j := range jobs {
521			key := j.origin + "\x00" + j.user
522			c, ok := clients[key]
523			if !ok {
524				c = newClient(j.origin, j.user, j.password)
525				clients[key] = c
526			}
527			data, same, err := j.record(ctx, o, c, date)
528			switch {
529			case err != nil:
530				return nil, nil, err
531			case same:
532				unchanged = append(unchanged, j.name)
533			default:
534				writes = append(writes, recordWrite{name: j.name, path: j.path, data: data})
535			}
536		}
537		return writes, unchanged, nil
538	}
539	
540	// record asks the bench for the answer of the job and returns the bytes of the
541	// fixture it would write; same is true when the file already holds that answer.
542	func (j recordJob) record(ctx context.Context, o RecordOptions, c *client, date string) (data []byte, same bool, err error) {
543		ex := j.current.Exchanges[0]
544		status, header, body, err := c.exchange(ctx, ex.Method, ex.Target, ex.RequestHeader)
545		if err != nil {
546			return nil, false, recordError("the answer to "+j.name+" could not be read", "check that the bench answers on its loopback ports", err)
547		}
548		if !benchVersionMatches(header.Get("Server"), o.Descriptor) {
549			return nil, false, recordError("the answer to "+j.name+" does not come from the Nexus version and edition the descriptor names", upCheck, nil)
550		}
551		if declaresJSON(header.Get("Content-Type")) && len(body) > 0 && !json.Valid(body) {
552			return nil, false, recordError("the answer to "+j.name+" is declared JSON and is not", "do not record this answer: a secret could hide from the redaction in it", nil)
553		}
554		answer := nexusfixture.Redact(nexusfixture.RawExchange{
555			Method: ex.Method, Target: ex.Target, Host: ex.Host, RequestHeader: ex.RequestHeader,
556			Status: status, Header: header, Body: body,
557		})
558		if answer.Stub == "" && answer.Header.Get("Content-Length") != "" {
559			// A redacted body is not as long as the one Nexus sent.
560			answer.Header.Set("Content-Length", strconv.Itoa(len(answer.Body)))
561		}
562		f := j.current
563		f.Meta.NexusVersion, f.Meta.Edition, f.Meta.NexusNote = o.Descriptor.NexusVersion, o.Descriptor.Edition, ""
564		f.Meta.Measured, f.Meta.RecordedBy = date, recordedBy
565		if f.Meta.Record == nexusfixture.RecordPending {
566			f.Meta.Record = ""
567		}
568		f.Exchanges = []nexusfixture.Exchange{answer}
569		data = nexusfixture.Format(f)
570	
571		// What will be written is read back and checked, not what was built.
572		back, err := nexusfixture.Parse(j.campaign, filepath.Base(j.path), data)
573		if err != nil || !bytes.Equal(nexusfixture.Format(back), data) {
574			return nil, false, recordError("the answer to "+j.name+" does not read back as a fixture", "do not record this answer", err)
575		}
576		if leaks := nexusfixture.CheckLeaks(j.name, data, recordTerms(o)); len(leaks) > 0 {
577			return nil, false, recordError("the answer to "+j.name+" would leak: "+describeLeaks(leaks), "nothing was written; fix the bench or the redaction", nil)
578		}
579		if holdsTerm(header, body, recordTerms(o)) {
