599	
600	// benchVersionMatches reports whether a Server header names the version and the
601	// edition of the descriptor.
602	func benchVersionMatches(server string, d Descriptor) bool {
603		m := serverHeader.FindStringSubmatch(server)
604		return m != nil && m[1] == d.NexusVersion && m[2] == d.Edition
605	}
