607	// declaresJSON reports whether a Content-Type is JSON.
608	func declaresJSON(contentType string) bool {
609		media, _, err := mime.ParseMediaType(contentType)
610		return err == nil && (media == "application/json" || strings.HasSuffix(media, "+json"))
611	}
