613	// ---- leaks ------------------------------------------------------------------------
614	
615	// recordTerms are the terms no written fixture may hold: the bench passwords,
616	// their Basic encodings, and the external deny list.
617	func recordTerms(o RecordOptions) []string {
618		terms := append([]string(nil), o.DenyTerms...)
619		for _, account := range []struct{ user, password string }{
620			{REDACTED, o.Secrets.AdminPassword},
621			{REDACTED, o.Secrets.PendingAdminPassword},
622			{REDACTED, o.Secrets.PullPassword},
623		} {
