226	// refuseLink refuses a campaign folder or a fixture file that is a symbolic
227	// link: a link could carry a run, which sends the bench credentials and rewrites
228	// files, to something that is not in the fixtures folder. A path that cannot be
229	// inspected is left to the read that follows.
230	func refuseLink(filePath, label string) error {
231		if info, err := os.Lstat(filePath); err == nil && info.Mode()&os.ModeSymlink != 0 {
232			return recordError(label+" is a symbolic link", "replace the link with the real file or folder", nil)
233		}
234		return nil
235	}
236	
237	// recordCampaigns returns the campaigns to read: the ones asked for, each a plain
238	// folder name of fsys (dir on disk), or every folder of fsys. A campaign that is
239	// a symbolic link is refused, asked for or found.
240	func recordCampaigns(dir string, fsys fs.FS, wanted []string) ([]string, error) {
241		if len(wanted) == 0 {
242			entries, err := fs.ReadDir(fsys, ".")
243			if err != nil {
244				return nil, recordError("the fixtures folder cannot be read", "check the folder", err)
245			}
246			var all []string
247			for _, e := range entries {
248				if strings.HasPrefix(e.Name(), ".") {
249					continue
250				}
251				if e.Type()&fs.ModeSymlink != 0 {
252					return nil, recordError("the campaign "+e.Name()+" is a symbolic link", "replace the link with the real folder", nil)
253				}
254				if e.IsDir() {
255					all = append(all, e.Name())
256				}
257			}
258			return all, nil
259		}
260		for _, c := range wanted {
261			if c == "." || !fs.ValidPath(c) || strings.Contains(c, "/") {
262				return nil, recordError("the campaign "+strconv.Quote(c)+" is not a campaign name", "name a folder of the fixtures folder, with no path", nil)
263			}
264			if err := refuseLink(filepath.Join(dir, c), c); err != nil {
265				return nil, err
266			}
267			if info, err := fs.Stat(fsys, c); err != nil || !info.IsDir() {
268				return nil, recordError("the campaign "+c+" does not exist", "check the campaign name", err)
269			}
270		}
271		return wanted, nil
272	}
