274	// planFixture reads one fixture file. It returns the reason when the fixture is
275	// skipped, an error when it must not be sent.
276	func planFixture(o RecordOptions, fsys fs.FS, filePath, campaign, fileName string) (recordJob, string, error) {
277		label := campaign + "/" + strings.TrimSuffix(fileName, ".http")
278		data, err := fs.ReadFile(fsys, path.Join(campaign, fileName))
279		if err != nil {
280			return recordJob{}, "", recordError(label+" cannot be read", "check the file", err)
281		}
282		f, err := nexusfixture.Parse(campaign, fileName, data)
283		if err != nil {
284			return recordJob{}, "", recordError(label+" is not a valid fixture", "fix the file", err)
285		}
286		if reason, ok := strings.CutPrefix(f.Meta.Record, "skip"); ok {
287			return recordJob{}, strings.TrimSpace(strings.TrimPrefix(reason, ":")), nil
288		}
289		if len(f.Exchanges) != 1 {
290			return recordJob{}, fmt.Sprintf("holds %d exchanges, only one is recorded yet", len(f.Exchanges)), nil
291		}
292		// The file is scanned as it stands: a request header outside Host, the
293		// credentials and Accept, or a query other than n and last, refuses it.
294		if leaks := nexusfixture.CheckLeaks(label, data, recordTerms(o)); len(leaks) > 0 {
295			return recordJob{}, "", recordError(label+" is refused before it is sent: "+describeLeaks(leaks), "fix the file", nil)
296		}
297		ex := f.Exchanges[0]
298		if reason := refusedRequest(ex.Method, ex.Target); reason != "" {
299			return recordJob{}, "", recordError(label+" asks for something the recorder does not send ("+reason+")", "record only GET requests of the closed list of paths", nil)
300		}
301		origin, ok := o.Origins[ex.Host]
302		if !ok {
303			return recordJob{}, "", recordError(label+" is recorded on "+ex.Host+", which has no origin", "give the origin of this host:port", nil)
304		}
305		job := recordJob{campaign: campaign, name: label, path: filePath, current: f, origin: origin}
306		switch f.Identity {
307		case nexusfixture.Admin:
308			job.user, job.password = REDACTED, o.Secrets.AdminPassword
309		case nexusfixture.Pull:
310			job.user, job.password = REDACTED, o.Secrets.PullPassword
311		}
312		if job.user != "" && job.password == "" {
313			return recordJob{}, "", recordError("the bench has no stored password for "+job.user+", the account of "+label, upCheck, nil)
314		}
315		return job, "", nil
316	}
