13	// Step 7a of DEVDESK-580 (PR2): the closed list of the recorder gets three
14	// additions, each behind a guard.
15	//
16	//   - A HEAD of a manifest. Through docker-hosted (host 30481, path
17	//     /repository/docker-hosted/...) it changes nothing and is accepted. Through
18	//     docker-proxy, docker-group or the group connector (30482) it can cache an
19	//     image in the proxy: it is sent only when the fixture says "effect: caches"
20	//     AND the run says --allow-cache-effects (RecordOptions.AllowCacheEffects),
21	//     and the report says which fixtures were such, so that the command can ask
22	//     for a reset. A HEAD answer has no body: it is written "<empty body>".
23	//   - A GET of a blob, only on docker-hosted and only for a fixture that says
24	//     "flow: redirects"; a GET of a manifest stays refused whatever the
25	//     fixture says. The token paths are not in this list at all: only a flow
26	//     sends them (record_flow_test.go).
27	//   - The identity "badcred": Basic with the user admin and the public wrong
28	//     password fakenexus.BadPassword, no stored password needed.
29	//
30	// Everything is checked before the first request, so a refusal leaves the bench
31	// and the files alone (e.refuse, e.requireNoRequest).
32	
33	const (
34		recDigest = "sha256:0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef"
35	
36		recHostedManifest    = "/repository/docker-hosted/v2/team/api/manifests/1.0.0"
37		recProxyManifest     = "/repository/docker-proxy/v2/mirror/uncached/manifests/1.0"
38		recGroupManifest     = "/repository/docker-group/v2/mirror/uncached/manifests/1.0"
39		recConnectorManifest = "/v2/mirror/uncached/manifests/1.0"
40		recHostedBlob        = "/repository/docker-hosted/v2/team/api/blobs/" + recDigest
41		recProxyBlob         = "/repository/docker-proxy/v2/mirror/cached/blobs/" + recDigest
42	
43		recMetaCaches    = "# effect: caches"
44		recMetaRedirects = "# flow: redirects"
45		recMetaBearer    = "# flow: bearer"
46	)
