48	// recMetaRequest is a request-only fixture text with extra header lines (flow,
49	// effect, state) before "# record: pending".
50	func recMetaRequest(meta []string, method, host, target string, auth bool, extra ...string) string {
51		text := recRequest(method, host, target, auth, extra...)
52		if len(meta) == 0 {
53			return text
54		}
55		return strings.Replace(text, "# record: pending\n", strings.Join(meta, "\n")+"\n# record: pending\n", 1)
56	}
57	
58	// addMeta adds a request-only fixture of the catalog campaign with extra header
59	// lines; the identity is the suffix of the name.
60	func (e *recEnv) addMeta(name string, meta []string, method, host, target string, extra ...string) string {
61		e.t.Helper()
62		return e.add("catalog", name, recMetaRequest(meta, method, host, target, !strings.HasSuffix(name, "--anon"), extra...))
63	}
