103		seen := e.rest.fixtureRequests()
104		if len(seen) != 1 || seen[0].method != "HEAD" || seen[0].uri != recHostedManifest || seen[0].user != "admin" {
105			t.Errorf("the bench saw %+v, want one HEAD as admin", seen)
106		}
107	}
