21	// Step 7b of DEVDESK-580 (PR2): a fixture that says "flow: bearer" or "flow:
22	// redirects" holds several exchanges, and the recorder follows them as DevDesk
23	// would, within limits.
24	//
25	// flow: bearer. The first exchange is sent as DevDesk sends it (Basic for admin,
26	// pull and badcred, nothing for anon). On a 401 whose WWW-Authenticate is a
27	// Bearer challenge, the recorder follows the challenge only when its realm is
28	// one of the origins of RecordOptions.Origins (matched on host:port, like the
29	// Host of a fixture) and the path of the realm is a token path: it sends the
30	// token request (the identity's Basic, the service and scope of the challenge),
31	// then the first request again with "Bearer <token>": three exchanges. A realm
32	// anywhere else ends the flow there: nothing is sent to it, the file holds the
33	// 401 only and a note, "realm off-origin, not followed". A 401 of the token
34	// request (the badcred identity) ends it too: two exchanges. No 401 at all: one
35	// exchange and the note "no challenge". The token read is a term no file and no
36	// output may hold, whatever the place; an answer that holds it where redaction
37	// would not show it is a refusal, as for a password.
38	//
39	// flow: redirects. A 3xx whose Location is an origin of Origins (and a request
40	// of the closed list) is followed, up to 5 hops, each one a recorded exchange
41	// that carries the same credentials as the first; a Location anywhere else is
42	// recorded and not followed, with the note "off-origin redirect, not followed";
43	// a chain that goes past 5 hops is an error and nothing is written.
44	//
45	// The file keeps its flow header. The note is written in the file; where is the
46	// recorder's choice. The recorded file is compared with what it holds, all of its
47	// exchanges, to say "unchanged".
48	//
49	// Chosen here, to be confirmed at review: the realm and the Location are matched
50	// on their host:port against the keys of Origins (the real Nexus names
51	// 127.0.0.1:30482, the test server listens elsewhere), and the request goes to the
52	// base URL of that key; a probe host that cannot resolve (realm-probe.invalid) is
53	// never reached, which a successful run proves.
54	
55	const (
56		recFlowToken   = "REDACTED"
57		recRealm       = "http://127.0.0.1:30482/v2/token"
58		recNoteRealm   = "realm off-origin, not followed"
59		recNoteNoChall = "no challenge"
60		recNoteRedir   = "off-origin redirect, not followed"
61	)
62	
63	// bearerConfig is what the bench of a Bearer flow does.
64	type bearerConfig struct {
65		token       string
66		realm       string // "" = recRealm
67		noChallenge bool   // the first request is answered 200
68		tokenStatus int    // 0 = 200, or the 401 a wrong password gets
69		expiresIn   int    // 0 = 300
70		catalog     string // "" = recCatalogBody
71		echoBody    bool   // the retry answer carries the token in a field redaction does not know
72		echoHeader  bool   // the retry answer carries the token in a header the fixture drops
73	}
74	
75	// bearerBench is a registry that asks for a Bearer token on /v2/_catalog and
76	// serves it on /v2/token for the bench passwords of recPasswords.
77	type bearerBench struct {
78		srv  *httptest.Server
79		mu   sync.Mutex
80		seen []recSeen
81		cfg  bearerConfig
82	}
83	
84	func newBearerBench(t *testing.T, cfg bearerConfig) *bearerBench {
85		t.Helper()
86		if cfg.token == "" {
87			cfg.token = REDACTED
88		}
89		b := &bearerBench{cfg: cfg}
90		b.srv = httptest.NewServer(http.HandlerFunc(b.serve))
91		t.Cleanup(b.srv.Close)
92		return b
93	}
94	
95	func (b *bearerBench) update(f func(*bearerConfig)) {
96		b.mu.Lock()
97		defer b.mu.Unlock()
98		f(&b.cfg)
99	}
100	
101	func (b *bearerBench) requests() []recSeen {
102		b.mu.Lock()
103		defer b.mu.Unlock()
104		return slices.Clone(b.seen)
105	}
106	
107	func (b *bearerBench) serve(w http.ResponseWriter, r *http.Request) {
108		user, pass, basic := r.BasicAuth()
109		b.mu.Lock()
110		b.seen = append(b.seen, recSeen{method: r.Method, uri: r.RequestURI, user: user, header: r.Header.Clone()})
111		c := b.cfg
112		b.mu.Unlock()
113	
114		h := w.Header()
115		h.Set("Server", recServer)
116		h.Set("Set-Cookie", "NXSESSIONID=rec-session; Path=/")
117		h.Set("Content-Type", "application/json")
118		if r.URL.Path == "/v2/token" {
119			switch {
120			case c.tokenStatus != 0:
121				w.WriteHeader(c.tokenStatus)
122			case basic && pass != recPasswords[user]:
123				w.WriteHeader(http.StatusUnauthorized)
124			default:
125				expires := c.expiresIn
126				if expires == 0 {
127					expires = 300
128				}
129				body, _ := json.Marshal(map[string]any{"token": c.token, "expires_in": expires})
130				_, _ = w.Write(body)
131			}
132			return
133		}
134		if !c.noChallenge && r.Header.Get("Authorization") != "Bearer "+c.token {
135			realm := c.realm
136			if realm == "" {
137				realm = recRealm
138			}
139			h.Set("Docker-Distribution-Api-Version", "registry/2.0")
140			h.Set("WWW-Authenticate", `Bearer realm="`+realm+`",service="`+recRealm+`",scope="registry:catalog:*"`)
141			w.WriteHeader(http.StatusUnauthorized)
142			_, _ = w.Write([]byte(`{"errors":[{"code":"UNAUTHORIZED","message":"authentication required"}]}`))
143			return
144		}
145		body := c.catalog
146		if body == "" {
147			body = recCatalogBody
148		}
149		if c.echoBody {
150			body = `{"repositories":[],"hint":"` + c.token + `"}`
151		}
152		if c.echoHeader {
153			h.Set("X-Echo", c.token)
154		}
155		_, _ = w.Write([]byte(body))
156	}
