178	// requireNoTerm fails when a file under dir holds a term, as is or URL-escaped.
179	func requireNoTerm(t *testing.T, dir string, terms ...string) {
180		t.Helper()
181		err := filepath.WalkDir(dir, func(path string, d os.DirEntry, err error) error {
182			if err != nil || d.IsDir() {
183				return err
184			}
185			data := mustRead(t, path)
186			for _, term := range terms {
187				for _, form := range []string{term, url.QueryEscape(term)} {
188					if bytes.Contains(data, []byte(form)) {
189						t.Errorf("%s holds a term that must never reach a file", path)
190					}
191				}
192			}
193			return nil
194		})
195		if err != nil {
196			t.Fatal(err)
197		}
198	}
