237	// queryOf parses the raw query of a target.
238	func queryOf(t *testing.T, target string) (path string, query url.Values) {
239		t.Helper()
240		path, raw, _ := strings.Cut(target, "?")
241		query, err := url.ParseQuery(raw)
242		if err != nil {
243			t.Fatalf("the query of %q does not parse: %v", target, err)
244		}
245		return path, query
246	}
