250	func TestRecordFlowBearerFollowsTheChallengeInThreeExchanges(t *testing.T) {
251		for _, id := range []string{"admin", "pull", "anon"} {
252			t.Run(id, func(t *testing.T) {
253				e, bench := flowEnv(t, bearerConfig{})
254				user := map[string]string{"admin": "admin", "pull": "bench-pull", "anon": ""}[id]
255				wantBasic := ""
256				if user != "" {
257					wantBasic = "Basic " + recBasic(user, recPasswords[user])
258				}
259				path := e.addMeta("catalog-bearer--"+id, []string{recMetaBearer}, "GET", recDockerHost, "/v2/_catalog")
260	
261				rep, err := e.record()
262				if err != nil {
263					t.Fatalf("RecordFixtures: %v", err)
264				}
265				if want := []string{"catalog/catalog-bearer--" + id}; !slices.Equal(rep.Written, want) || len(rep.Skipped) != 0 {
266					t.Errorf("report = %+v, want only %v written: a flow fixture is recorded, not skipped", rep, want)
267				}
268	
269				// What went over the wire.
270				seen := bench.requests()
271				if len(seen) != 3 {
272					t.Fatalf("the bench saw %d request(s), want 3 (the call, the token, the call with it): %+v", len(seen), seen)
273				}
274				if seen[0].uri != "/v2/_catalog" || seen[0].header.Get("Authorization") != wantBasic {
275					t.Errorf("request 1 = %s with %q, want the call as DevDesk sends it (%q)", seen[0].uri, seen[0].header.Get("Authorization"), wantBasic)
276				}
277				tokenPath, query := queryOf(t, seen[1].uri)
278				if tokenPath != "/v2/token" || query.Get("service") != recRealm || query.Get("scope") != "registry:catalog:*" {
279					t.Errorf("request 2 = %s (query %v), want the token request of the challenge", seen[1].uri, query)
280				}
281				if seen[1].header.Get("Authorization") != wantBasic {
282					t.Errorf("the token request carries %q, want the Basic of the identity (%q)", seen[1].header.Get("Authorization"), wantBasic)
283				}
284				if seen[2].uri != "/v2/_catalog" || seen[2].header.Get("Authorization") != "Bearer "+recFlowToken {
285					t.Errorf("request 3 = %s with %q, want the first request again with the Bearer token", seen[2].uri, seen[2].header.Get("Authorization"))
286				}
287	
288				// What was written.
289				f := requireFlowRecorded(t, path, 3, recFlowToken)
290				if f.Meta.Flow != nexusfixture.FlowBearer {
291					t.Errorf("flow = %q, want it kept", f.Meta.Flow)
292				}
293				ex1, ex2, ex3 := f.Exchanges[0], f.Exchanges[1], f.Exchanges[2]
294				wantAuth := ""
295				if user != "" {
296					wantAuth = "Basic <redacted>"
297				}
298				if ex1.Status != 401 || !strings.Contains(ex1.Header.Get("WWW-Authenticate"), `realm="`+recRealm+`"`) {
299					t.Errorf("exchange 1 = %d %q, want the 401 and its challenge", ex1.Status, ex1.Header.Get("WWW-Authenticate"))
300				}
301				tp, q := queryOf(t, ex2.Target)
302				if ex2.Host != recDockerHost || tp != "/v2/token" || q.Get("service") != recRealm || q.Get("scope") != "registry:catalog:*" || ex2.Status != 200 {
303					t.Errorf("exchange 2 = %s %s on %s -> %d, want the token request on %s", ex2.Method, ex2.Target, ex2.Host, ex2.Status, recDockerHost)
304				}
305				var tokenBody struct {
306					Token     string `json:"token"`
307					ExpiresIn int    `json:"expires_in"`
308				}
309				if err := json.Unmarshal(ex2.Body, &tokenBody); err != nil || tokenBody.Token != "<redacted>" || tokenBody.ExpiresIn != 300 {
310					t.Errorf("token body = %q (%v), want the token redacted and expires_in kept", ex2.Body, err)
311				}
312				if ex3.Target != "/v2/_catalog" || ex3.Status != 200 || string(ex3.Body) != recCatalogBody {
313					t.Errorf("exchange 3 = %s -> %d %q, want the catalog", ex3.Target, ex3.Status, ex3.Body)
314				}
315				for i, want := range []string{wantAuth, wantAuth, "Bearer <redacted>"} {
316					if got := f.Exchanges[i].RequestHeader.Get("Authorization"); got != want {
317						t.Errorf("exchange %d: Authorization = %q, want %q", i+1, got, want)
318					}
319				}
320	
321				// The token is nowhere.
322				requireNoTerm(t, e.dir, recFlowToken)
323			})
324		}
325	}
