65	// headAnswer is what a HEAD of a manifest gets: the digest and the length, no body.
66	func headAnswer() recAnswer {
67		return recAnswer{
68			contentType: "application/vnd.docker.distribution.manifest.v2+json",
69			header:      http.Header{"Docker-Content-Digest": {recDigest}, "Content-Length": {"1234"}},
70		}
71	}
