210	// requireFlowRecorded is requireRecorded for a fixture of several exchanges: it
211	// reads back, writes back to the same bytes, leaks nothing (the token included)
212	// and says who wrote it and when.
213	func requireFlowRecorded(t *testing.T, path string, exchanges int, terms ...string) nexusfixture.Fixture {
214		t.Helper()
215		data := mustRead(t, path)
216		f := parseRecorded(t, path)
217		if got := nexusfixture.Format(f); !bytes.Equal(got, data) {
218			t.Errorf("Format(Parse(file)) differs from the file:\n%s\n--- want\n%s", got, data)
219		}
220		if leaks := nexusfixture.CheckLeaks(f.Name, data, slices.Concat(recExact(), terms)); len(leaks) != 0 {
221			t.Errorf("the recorded file leaks: %+v", leaks)
222		}
223		if f.Meta.RecordedBy != recRecordedBy || f.Meta.Measured != "2026-11-18" || f.Meta.Record == nexusfixture.RecordPending {
224			t.Errorf("recorded-by %q, measured %q, record %q: not the header of a recording", f.Meta.RecordedBy, f.Meta.Measured, f.Meta.Record)
225		}
226		if len(f.Exchanges) != exchanges {
227			t.Fatalf("%d exchange(s), want %d:\n%s", len(f.Exchanges), exchanges, data)
228		}
229		for i, ex := range f.Exchanges {
230			if ex.Status == 0 {
231				t.Errorf("exchange %d has no answer", i+1)
232			}
233		}
234		return f
235	}
