138	// slowBench answers a catalog after delay, or gives up when the client does.
139	func slowBench(t *testing.T, delay time.Duration) *httptest.Server {
140		t.Helper()
141		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
142			select {
143			case <-time.After(delay):
144			case <-r.Context().Done():
145				return
146			}
147			w.Header().Set("Server", recServer)
148			w.Header().Set("Content-Type", "application/json")
149			_, _ = w.Write([]byte(recCatalogBody))
150		}))
151		t.Cleanup(srv.Close)
152		return srv
153	}
