155	func TestRecordRequestTimeoutDefaultsToFifteenSeconds(t *testing.T) {
156		if defaultRecordTimeout != clientTimeout {
157			t.Errorf("defaultRecordTimeout = %v, want the 15 s clientTimeout of today", defaultRecordTimeout)
158		}
159		tests := []struct {
160			name string
161			opts RecordOptions
162			want time.Duration
163		}{
164			{"not set", RecordOptions{}, defaultRecordTimeout},
165			{"set", RecordOptions{RequestTimeout: 45 * time.Second}, 45 * time.Second},
166			{"set below the default", RecordOptions{RequestTimeout: 2 * time.Second}, 2 * time.Second},
167		}
168		for _, tt := range tests {
169			t.Run(tt.name, func(t *testing.T) {
170				if got := recordRequestTimeout(tt.opts); got != tt.want {
171					t.Errorf("recordRequestTimeout = %v, want %v", got, tt.want)
172				}
173			})
174		}
175	}
