177	func TestRecordGivesUpOnAnAnswerThatTakesLongerThanTheRequestTimeout(t *testing.T) {
178		e := newRecEnv(t)
179		e.opts.Origins[recDockerHost] = slowBench(t, 1500*time.Millisecond).URL
180		e.opts.RequestTimeout = 150 * time.Millisecond
181		e.addGood()
182		e.pending("z-slow--admin", recDockerHost, "/v2/_catalog")
183	
184		start := time.Now()
185		be := e.refuse("z-slow--admin")
186		if !strings.Contains(be.Error(), "could not be read") {
187			t.Errorf("the error %q does not say the answer could not be read", be.Error())
188		}
189		if took := time.Since(start); took > time.Second {
190			t.Errorf("the run took %v: the request was not bounded by RequestTimeout (150ms)", took)
191		}
