161	// nextLine cuts the first line of s; ok is false when s is empty.
162	func nextLine(s string) (line, rest string, ok bool) {
163		if s == "" {
164			return "", "", false
165		}
166		line, rest, _ = strings.Cut(s, "\n")
167		return line, rest, true
168	}
169	
170	// parseMeta reads the "# key: value" lines and the blank line after them.
171	func parseMeta(text string) (Meta, string, error) {
172		raw := map[string]string{}
173		for strings.HasPrefix(text, "#") {
174			var line string
175			line, text, _ = nextLine(text)
176			body, ok := strings.CutPrefix(line, "# ")
177			if !ok {
178				return Meta{}, "", fmt.Errorf("malformed header line, want \"# key: value\"")
179			}
180			key, value, _ := strings.Cut(body, ":")
181			if !isKnownHeader(key) {
182				return Meta{}, "", fmt.Errorf("unknown header %q", key)
183			}
184			if _, dup := raw[key]; dup {
185				return Meta{}, "", fmt.Errorf("header %q given twice", key)
186			}
187			raw[key] = strings.TrimSpace(value)
188		}
189		for _, key := range requiredHeaders {
190			if raw[key] == "" {
191				return Meta{}, "", fmt.Errorf("missing %s header", key)
192			}
193		}
194		m := Meta{
195			Scenario: raw["scenario"], Measured: raw["measured"], Account: raw["account"], Redacted: raw["redacted"],
196			State: raw["state"], Flow: raw["flow"], Effect: raw["effect"], Record: raw["record"], RecordedBy: raw["recorded-by"],
197		}
198		if err := parseNexus(&m, raw["nexus"]); err != nil {
199			return Meta{}, "", err
200		}
201		if err := checkMeasured(m.Measured); err != nil {
202			return Meta{}, "", err
203		}
204		if err := checkFlowAndEffect(m); err != nil {
205			return Meta{}, "", err
206		}
207		if err := checkRecord(m.Record); err != nil {
208			return Meta{}, "", err
209		}
210		line, rest, ok := nextLine(text)
211		if !ok || line != "" {
212			return Meta{}, "", fmt.Errorf("a blank line must separate the headers from the request")
213		}
214		return m, rest, nil
215	}
216	
217	func isKnownHeader(key string) bool {
218		for _, k := range requiredHeaders {
219			if k == key {
220				return true
221			}
222		}
223		for _, k := range optionalHeaders {
224			if k == key {
225				return true
226			}
227		}
228		return false
229	}
230	
231	// parseNexus reads "<version> <EDITION> [(free text)]".
232	func parseNexus(m *Meta, v string) error {
233		version, rest, _ := strings.Cut(v, " ")
234		edition, rest, _ := strings.Cut(strings.TrimSpace(rest), " ")
235		rest = strings.TrimSpace(rest)
236		if !versionPattern.MatchString(version) {
237			return fmt.Errorf("nexus header: %q is not a version", version)
238		}
239		if edition == "" {
240			return fmt.Errorf("nexus header: the edition is missing after the version")
241		}
242		m.NexusVersion, m.Edition = version, edition
243		if rest == "" {
244			return nil
245		}
246		inner, ok := strings.CutPrefix(rest, "(")
247		if ok {
248			inner, ok = strings.CutSuffix(inner, ")")
249		}
250		if !ok {
251			return fmt.Errorf("nexus header: the text after the edition must be in parentheses")
252		}
253		m.NexusNote = inner
254		return nil
255	}
256	
257	func checkMeasured(v string) error {
258		if len(v) < len("2006-01-02") {
259			return fmt.Errorf("measured header: %q does not start with a YYYY-MM-DD date", v)
260		}
261		if _, err := time.Parse("2006-01-02", v[:10]); err != nil {
262			return fmt.Errorf("measured header: does not start with a YYYY-MM-DD date")
263		}
264		if after := v[10:]; after != "" && !strings.HasPrefix(after, ",") {
265			return fmt.Errorf("measured header: the date may only be followed by \", free text\"")
266		}
267		return nil
268	}
269	
270	func checkFlowAndEffect(m Meta) error {
271		if m.Flow != "" && m.Flow != FlowBearer && m.Flow != FlowRedirects {
272			return fmt.Errorf("flow header: %q is not %s or %s", m.Flow, FlowBearer, FlowRedirects)
273		}
274		if m.Effect != "" && m.Effect != EffectCaches {
275			return fmt.Errorf("effect header: %q is not %s", m.Effect, EffectCaches)
276		}
277		return nil
278	}
279	
280	func checkRecord(v string) error {
281		if reason, ok := strings.CutPrefix(v, "skip: "); ok && strings.TrimSpace(reason) != "" {
282			return nil
283		}
284		if v == "" || v == "replay" || v == RecordPending {
285			return nil
286		}
287		return fmt.Errorf("record header: %q is not replay, pending or skip: <reason>", v)
288	}
289	
290	// splitExchanges cuts the text after the header at each "###" line.
291	func splitExchanges(text string) []string {
292		parts := strings.Split(text, "\n"+exchangeSep+"\n")
293		for i := 0; i < len(parts)-1; i++ {
294			parts[i] += "\n" // the line break the separator consumed
295		}
296		return parts
297	}
298	
299	func parseExchange(text string, pending bool) (Exchange, error) {
300		var ex Exchange
301		line, text, _ := nextLine(text)
302		fields := strings.Fields(line)
303		if len(fields) != 3 || fields[2] != httpVersion {
304			return ex, fmt.Errorf("request line must be \"METHOD target %s\"", httpVersion)
305		}
306		ex.Method, ex.Target = fields[0], fields[1]
307	
308		header, text, blank, err := readHeaders(text)
309		if err != nil {
310			return ex, fmt.Errorf("request: %w", err)
311		}
312		ex.Host = header.Get("Host")
313		header.Del("Host")
314		ex.RequestHeader = header
315		if ex.Host == "" {
316			return ex, fmt.Errorf("the request has no Host header")
317		}
318	
319		if !blank || text == "" {
320			if pending {
321				return ex, nil
322			}
323			return ex, fmt.Errorf("the response is missing (only a pending fixture may hold a request alone)")
324		}
325		if pending {
326			return ex, fmt.Errorf("a pending fixture must not carry a response")
327		}
328		return ex, parseResponse(&ex, text)
329	}
330	
331	func parseResponse(ex *Exchange, text string) error {
332		line, text, _ := nextLine(text)
333		rest, ok := strings.CutPrefix(line, httpVersion+" ")
334		if !ok {
335			return fmt.Errorf("status line must be \"%s <code> <reason>\"", httpVersion)
336		}
337		code, reason, _ := strings.Cut(rest, " ")
338		status, err := strconv.Atoi(code)
339		if err != nil || status < 100 || status > 599 {
340			return fmt.Errorf("status code is not a number from 100 to 599")
341		}
342		// Format trims the status line, so a blank or padded phrase cannot round-trip.
343		ex.Status, ex.Reason = status, strings.TrimSpace(reason)
344	
345		header, text, blank, err := readHeaders(text)
346		if err != nil {
347			return fmt.Errorf("response: %w", err)
348		}
349		if !blank {
350			return fmt.Errorf("a blank line must separate the response headers from the body")
351		}
352		ex.Header = header
353	
354		body := strings.TrimSuffix(text, "\n")
355		if body == stubEmpty || isOmittedStub(body) {
356			ex.Stub = body
357		} else {
358			ex.Body = []byte(unescapeBody(body))
359		}
360		return nil
361	}
362	
363	// isOmittedStub reports whether a body is one of the two summaries Redact writes
364	// in place of a body: "<HTML body omitted: ...>" or "<body omitted: ...>".
365	func isOmittedStub(body string) bool {
366		return (strings.HasPrefix(body, stubHTMLStart) || strings.HasPrefix(body, stubOmittedStart)) && strings.HasSuffix(body, ">")
367	}
368	
369	// isSeparatorLike reports whether a body line is "###" preceded by any number
370	// of backslashes: the lines Format escapes and Parse unescapes.
371	func isSeparatorLike(line string) bool {
372		return strings.HasSuffix(line, exchangeSep) && strings.Trim(line[:len(line)-len(exchangeSep)], `\`) == ""
373	}
374	
375	// mapSeparatorLikeLines applies fn to each body line that isSeparatorLike.
376	func mapSeparatorLikeLines(body string, fn func(string) string) string {
377		lines := strings.Split(body, "\n")
378		for i, l := range lines {
379			if isSeparatorLike(l) {
380				lines[i] = fn(l)
381			}
382		}
383		return strings.Join(lines, "\n")
384	}
385	
386	func escapeBody(body []byte) []byte {
387		return []byte(mapSeparatorLikeLines(string(body), func(l string) string { return `\` + l }))
388	}
389	
390	func unescapeBody(body string) string {
391		return mapSeparatorLikeLines(body, func(l string) string { return l[1:] })
392	}
393	
394	// readHeaders reads "Name: value" lines up to a blank line. blank is false when
395	// the text ended first.
396	func readHeaders(text string) (h http.Header, rest string, blank bool, err error) {
397		h = http.Header{}
398		for {
399			var line string
400			var ok bool
401			line, text, ok = nextLine(text)
402			switch {
403			case !ok:
404				return h, "", false, nil
405			case line == "":
406				return h, text, true, nil
407			case strings.HasPrefix(line, "HTTP/"):
408				return nil, "", false, fmt.Errorf("a blank line must separate the request from the response")
409			}
410			name, value, found := strings.Cut(line, ":")
411			if !found || name == "" {
412				return nil, "", false, fmt.Errorf("malformed header line, want \"Name: value\"")
413			}
414			h.Add(textproto.CanonicalMIMEHeaderKey(name), strings.TrimPrefix(value, " "))
415		}
416	}
417	
418	// Format writes a fixture in the file format; Format(Parse(b)) == b for a file
419	// the recorder or the NX-03 import wrote.
420	func Format(f Fixture) []byte {
421		var b bytes.Buffer
422		writeMeta(&b, f.Meta)
423		for i, ex := range f.Exchanges {
424			if i == 0 {
425				b.WriteString("\n")
426			} else {
427				b.WriteString(exchangeSep + "\n")
428			}
429			writeExchange(&b, ex)
430		}
431		return b.Bytes()
432	}
433	
434	func writeMeta(b *bytes.Buffer, m Meta) {
435		nexus := m.NexusVersion + " " + m.Edition
436		if m.NexusNote != "" {
437			nexus += " (" + m.NexusNote + ")"
438		}
439		lines := []struct{ key, value string }{
440			{"scenario", m.Scenario}, {"nexus", nexus}, {"measured", m.Measured},
441			{"account", m.Account}, {"redacted", m.Redacted},
442		}
443		for _, l := range lines {
444			fmt.Fprintf(b, "# %s: %s\n", l.key, l.value)
445		}
446		for _, l := range []struct{ key, value string }{
447			{"state", m.State}, {"flow", m.Flow}, {"effect", m.Effect}, {"record", m.Record}, {"recorded-by", m.RecordedBy},
448		} {
449			if l.value != "" {
450				fmt.Fprintf(b, "# %s: %s\n", l.key, l.value)
451			}
452		}
453	}
454	
455	func writeExchange(b *bytes.Buffer, ex Exchange) {
456		fmt.Fprintf(b, "%s %s %s\nHost: %s\n", ex.Method, ex.Target, httpVersion, ex.Host)
457		writeHeaders(b, ex.RequestHeader, requestOrder, "Host")
458		if ex.Status == 0 {
459			return
460		}
461		reason := ex.Reason
462		if reason == "" {
463			reason = http.StatusText(ex.Status)
464		}
465		b.WriteString("\n" + strings.TrimSpace(fmt.Sprintf("%s %d %s", httpVersion, ex.Status, reason)) + "\n")
466		writeHeaders(b, ex.Header, responseOrder)
467		b.WriteString("\n")
468		if ex.Stub != "" {
469			b.WriteString(ex.Stub)
470		} else {
471			b.Write(escapeBody(ex.Body))
472		}
473		b.WriteString("\n")
474	}
475	
476	// writeHeaders writes the headers in a fixed order (the preferred names first,
477	// then the others sorted) so that a regeneration does not reshuffle a file.
478	func writeHeaders(b *bytes.Buffer, h http.Header, preferred []string, skip ...string) {
479		skipped := map[string]bool{}
480		for _, s := range skip {
481			skipped[s] = true
482		}
483		var names []string
484		for _, p := range preferred {
485			if _, ok := h[p]; ok && !skipped[p] {
486				names = append(names, p)
487			}
488		}
489		var others []string
490		for k := range h {
491			if skipped[k] || contains(preferred, k) {
492				continue
493			}
