35	func TestRecordStateSelectsTheFixturesOfTheStateOfTheBench(t *testing.T) {
36		tests := []struct {
37			name        string
38			state       BenchState
39			wantWritten []string
40			wantSkipped []string
41			wantRest    int // fixture requests on the rest origin
42			wantDocker  int
43		}{
44			{
45				name: "nominal", state: StateNominal,
46				wantWritten: []string{"catalog/a-nominal--admin"},
47				wantSkipped: []string{"catalog/b-cut--admin", "catalog/c-cut-text--admin"},
48				wantRest:    1,
49			},
50			{
51				name: "upstream cut", state: StateUpstreamCut,
52				wantWritten: []string{"catalog/b-cut--admin", "catalog/c-cut-text--admin"},
53				wantSkipped: []string{"catalog/a-nominal--admin"},
54				wantDocker:  2,
55			},
56		}
57		for _, tt := range tests {
58			t.Run(tt.name, func(t *testing.T) {
59				e := newRecEnv(t)
60				e.opts.State = tt.state
61				e.rest.answer("admin", recGoodTarget, recAnswer{contentType: "application/json", body: `[]`})
62				e.docker.answer("admin", "/v2/_catalog", recAnswer{contentType: "application/json", body: recCatalogBody})
63				e.docker.answer("admin", "/v2/docker-hosted/_catalog", recAnswer{contentType: "application/json", body: recCatalogBody})
64				e.pending("a-nominal--admin", recRESTHost, recGoodTarget)
65				e.addMeta("b-cut--admin", []string{recMetaUpstreamCut}, "GET", recDockerHost, "/v2/_catalog")
66				e.addMeta("c-cut-text--admin", []string{"# state: upstream-cut (the proxy is blocked)"}, "GET", recDockerHost, "/v2/docker-hosted/_catalog")
67				before := recSnapshot(t, e.dir)
68	
69				rep, err := e.record()
70				if err != nil {
71					t.Fatalf("RecordFixtures: %v", err)
72				}
73				if !slices.Equal(rep.Written, tt.wantWritten) {
74					t.Errorf("Written = %v, want %v", rep.Written, tt.wantWritten)
75				}
76				var skipped []string
77				for _, s := range rep.Skipped {
78					name, reason, _ := strings.Cut(s, ": ")
79					skipped = append(skipped, name)
80					if !strings.Contains(strings.ToLower(reason), "state") {
81						t.Errorf("the skip %q does not say it is a matter of state", s)
82					}
83				}
84				if !slices.Equal(recSorted(skipped), tt.wantSkipped) {
85					t.Errorf("Skipped = %v, want %v", rep.Skipped, tt.wantSkipped)
86				}
87				if got := len(e.rest.fixtureRequests()); got != tt.wantRest {
88					t.Errorf("the REST origin saw %d fixture request(s), want %d", got, tt.wantRest)
89				}
90				if got := len(e.docker.requests()); got != tt.wantDocker {
91					t.Errorf("the connector saw %d request(s), want %d: a skipped fixture is never requested", got, tt.wantDocker)
92				}
93				// A skipped file is left alone, bytes and modification time.
94				after := recSnapshot(t, e.dir)
95				for _, name := range tt.wantSkipped {
96					p := e.dir + "/" + name + ".http"
97					if string(before[p].data) != string(after[p].data) || !before[p].mod.Equal(after[p].mod) {
98						t.Errorf("%s was touched though it is skipped", name)
99					}
100				}
101			})
102		}
103	}
