46			t.Errorf("cluster events = %v, want %v (all: %v)", got, want, r.h.eventList())
47		}
48		r.h.requireNotCalled("newForwarder", "newCopier", "newInitial", "deploy", "provision", "ensureUpstream", "seed",
49			"cutUpstream", "restoreUpstream", "reset", "unblockProxy", "destroy", "readImages:docker-hosted", "readImages:docker-proxy")
50	}
