41	// requireOnlyTheStateReads fails when the command did more to the cluster than
42	// the preflight OpRecord and the read of the upstream.
43	func requireOnlyTheStateReads(t *testing.T, r *recordRig) {
44		t.Helper()
45		if got, want := r.h.opsEvents(), []string{"preflight:OpRecord", "readUpstream"}; !slices.Equal(got, want) {
46			t.Errorf("cluster events = %v, want %v (all: %v)", got, want, r.h.eventList())
47		}
48		r.h.requireNotCalled("newForwarder", "newCopier", "newInitial", "deploy", "provision", "ensureUpstream", "seed",
49			"cutUpstream", "restoreUpstream", "reset", "unblockProxy", "destroy", "readImages:docker-hosted", "readImages:docker-proxy")
50	}
